<?php
declare(strict_types=1); function mg_personal_workflows_create_bundle(PDO $pdo, int $userId, array $input): array { mg_personal_workflows_require_schema($pdo); $context=mg_personal_workflows_context($pdo,$userId,$input); $ids=mg_personal_workflows_context_columns($context); $title=mg_personal_agent_text($input['title'] ?? '',190); if($title==='') throw new InvalidArgumentException('Bundle title is required.'); $description=mg_personal_agent_nullable_text($input['description'] ?? null,5000); $target=mg_personal_workflows_cents($input['target_budget'] ?? null,true); $currency=mg_personal_agent_currency($input['currency'] ?? 'USD'); $planId=($context['type'] ?? '')==='plan' ? (int)($ids['plan_id'] ?? 0) : null; if($planId===0)$planId=null; $planPublicId=mg_personal_agent_text($input['plan_id'] ?? '',80); if($planPublicId!=='') { $stmt=$pdo->prepare('SELECT id FROM user_gifting_plans WHERE owner_user_id=? AND public_id=? LIMIT 1'); $stmt->execute([$userId,$planPublicId]); $planId=(int)($stmt->fetchColumn() ?: 0); if($planId<1) throw new RuntimeException('Gifting plan not found.'); } $publicId=mg_public_uuid(); $pdo->prepare("INSERT INTO user_gift_bundles
        (public_id,owner_user_id,plan_id,list_id,user_contact_id,contact_user_id,title,description,target_budget_cents,currency,status,approval_required,created_at,updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,'draft',1,NOW(),NOW())") ->execute([$publicId,$userId,$planId,$ids['list_id'] ?? null,$ids['user_contact_id'] ?? null,$ids['contact_user_id'] ?? null,$title,$description,$target,$currency]); mg_audit('user_gift_bundle.created','user_gift_bundle',['bundle_id'=>$publicId,'context_type'=>$context['type'],'approval_required'=>true],$userId); foreach(mg_personal_workflows_bundles($pdo,$userId) as $bundle) if($bundle['id']===$publicId) return $bundle; throw new RuntimeException('Unable to load the gift bundle.'); } function mg_personal_workflows_add_bundle_item(PDO $pdo, int $userId, string $bundlePublicId, array $input): array { mg_personal_workflows_require_schema($pdo); $bundleStmt=$pdo->prepare("SELECT id,status,currency FROM user_gift_bundles WHERE owner_user_id=? AND public_id=? LIMIT 1"); $bundleStmt->execute([$userId,$bundlePublicId]); $bundle=$bundleStmt->fetch(PDO::FETCH_ASSOC); if(!$bundle) throw new RuntimeException('Gift bundle not found.'); if((string)$bundle['status']==='archived') throw new RuntimeException('Archived bundles cannot be changed.'); $itemType=mg_personal_agent_text($input['item_type'] ?? 'custom',30); if(!in_array($itemType,['catalog_product','custom'],true)) throw new InvalidArgumentException('Choose a valid bundle item type.'); $catalogProductId=null;$label=null;$unitCents=null;$currency=mg_personal_agent_currency($input['currency'] ?? $bundle['currency']); if($itemType==='catalog_product') { $productPublicId=mg_personal_agent_text($input['product_id'] ?? '',80); if($productPublicId==='') throw new InvalidArgumentException('Choose a published product.'); $stmt=$pdo->prepare("SELECT cp.id,cpv.title,cpv.unit_value_cents,cpv.currency
            FROM catalog_products cp INNER JOIN catalog_product_versions cpv ON cpv.id=cp.current_version_id
            WHERE cp.public_id=? AND cp.status='published' AND cpv.version_status='published' LIMIT 1"); $stmt->execute([$productPublicId]); $product=$stmt->fetch(PDO::FETCH_ASSOC); if(!$product) throw new RuntimeException('Published product not found.'); $catalogProductId=(int)$product['id'];$label=(string)$product['title'];$unitCents=(int)$product['unit_value_cents'];$currency=(string)$product['currency']; } else { $label=mg_personal_agent_text($input['custom_label'] ?? '',190); if($label==='') throw new InvalidArgumentException('Custom item label is required.'); $unitCents=mg_personal_workflows_cents($input['unit_value'] ?? null,true); } $quantity=max(1,min(999,(int)($input['quantity'] ?? 1))); $notes=mg_personal_agent_nullable_text($input['notes'] ?? null,1000); $sortOrder=max(0,min(100000,(int)($input['sort_order'] ?? 100))); $publicId=mg_public_uuid(); $pdo->prepare("INSERT INTO user_gift_bundle_items
        (public_id,bundle_id,catalog_product_id,item_type,custom_label,quantity,unit_value_cents,currency,notes,sort_order,status,created_at,updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,'selected',NOW(),NOW())") ->execute([$publicId,(int)$bundle['id'],$catalogProductId,$itemType,$itemType==='custom'?$label:null,$quantity,$unitCents,$currency,$notes,$sortOrder]); $pdo->prepare("UPDATE user_gift_bundles SET status='draft',updated_at=NOW() WHERE id=?")->execute([(int)$bundle['id']]); mg_audit('user_gift_bundle.item_added','user_gift_bundle_item',['bundle_id'=>$bundlePublicId,'item_id'=>$publicId,'item_type'=>$itemType,'commerce_executed'=>false],$userId); foreach(mg_personal_workflows_bundles($pdo,$userId) as $item) if($item['id']===$bundlePublicId) return $item; throw new RuntimeException('Unable to load the gift bundle.'); } function mg_personal_workflows_update_bundle(PDO $pdo, int $userId, string $bundlePublicId, string $action): array { $action=mg_personal_agent_text($action,30); $map=['ready'=>'ready','reopen'=>'draft','archive'=>'archived']; if(!isset($map[$action])) throw new InvalidArgumentException('Invalid bundle action.'); $stmt=$pdo->prepare('SELECT id,status FROM user_gift_bundles WHERE owner_user_id=? AND public_id=? LIMIT 1'); $stmt->execute([$userId,$bundlePublicId]); $bundle=$stmt->fetch(PDO::FETCH_ASSOC); if(!$bundle) throw new RuntimeException('Gift bundle not found.'); $allowed=['draft'=>['ready','archive'],'ready'=>['reopen','archive'],'archived'=>[]]; if(!in_array($action,$allowed[(string)$bundle['status']] ?? [],true)) throw new RuntimeException('That bundle transition is not allowed.'); if($action==='ready') { $count=$pdo->prepare("SELECT COUNT(*) FROM user_gift_bundle_items WHERE bundle_id=? AND status<>'removed'"); $count->execute([(int)$bundle['id']]); if((int)$count->fetchColumn()<1) throw new RuntimeException('Add at least one item before marking a bundle ready.'); } $pdo->prepare('UPDATE user_gift_bundles SET status=?,updated_at=NOW() WHERE id=? AND owner_user_id=?')->execute([$map[$action],(int)$bundle['id'],$userId]); mg_audit('user_gift_bundle.status_updated','user_gift_bundle',['bundle_id'=>$bundlePublicId,'from'=>$bundle['status'],'to'=>$map[$action],'approval_required'=>true],$userId); foreach(mg_personal_workflows_bundles($pdo,$userId) as $item) if($item['id']===$bundlePublicId) return $item; throw new RuntimeException('Gift bundle not found.'); } function mg_personal_workflows_remove_bundle_item(PDO $pdo, int $userId, string $bundlePublicId, string $itemPublicId): array { $stmt=$pdo->prepare("UPDATE user_gift_bundle_items bi INNER JOIN user_gift_bundles b ON b.id=bi.bundle_id
        SET bi.status='removed',bi.updated_at=NOW(),b.status='draft',b.updated_at=NOW()
        WHERE b.owner_user_id=? AND b.public_id=? AND bi.public_id=? AND bi.status<>'removed'"); $stmt->execute([$userId,$bundlePublicId,$itemPublicId]); if($stmt->rowCount()<1) throw new RuntimeException('Bundle item not found.'); mg_audit('user_gift_bundle.item_removed','user_gift_bundle_item',['bundle_id'=>$bundlePublicId,'item_id'=>$itemPublicId],$userId); foreach(mg_personal_workflows_bundles($pdo,$userId) as $item) if($item['id']===$bundlePublicId) return $item; throw new RuntimeException('Gift bundle not found.'); } 